import{_ as r,C as t,o as s,c as i,E as a,a2 as c}from"./chunks/framework.BOeh4kYD.js";const h="/joinwell52/assets/control-intent-20260917/backup-without-history.figure.en.svg",b=JSON.parse('{"title":"More backups. Less history. How does that happen?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"More backups. Less history. How does that happen?","date":"2026-09-17","published_date":"2026-09-17","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"More backups. Less history. How does that happen?","summary":"A full backup list can hide an empty history. Running the original merge code shows how unchanged saves can evict the version you actually need.","cover":"/assets/control-intent-20260917/backup-without-history.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded original-code experiments; scope in article","pageClass":"control-intent-article"},"headers":[],"relativePath":"en/engineering/2026-09-17-backup-without-history.md","filePath":"en/engineering/2026-09-17-backup-without-history.md","lastUpdated":1789614884000}'),l={name:"en/engineering/2026-09-17-backup-without-history.md"};function d(p,e,u,g,m,f){const n=t("ArticleCover"),o=t("ArticleTableScroll");return s(),i("div",null,[a(n,{image:"/assets/control-intent-20260917/backup-without-history.cover-v1.png",kicker:"Open-source engineering · Experimental research",title:"More backups. Less history. How does that happen?",summary:"A full backup list can hide an empty history. Running the original merge code shows how unchanged saves can evict the version you actually need.",version:"2026-09-17",languageHref:"/zh/engineering/2026-09-17-backup-without-history",languageLabel:"中文"}),a(o,{language:"en"}),e[0]||(e[0]=c('<h1 id="more-backups-less-history-how-does-that-happen" tabindex="-1">More backups. Less history. How does that happen? <a class="header-anchor" href="#more-backups-less-history-how-does-that-happen" aria-label="Permalink to &quot;More backups. Less history. How does that happen?&quot;">​</a></h1><p>You open the backup folder and find ten neatly named files. Only when you need yesterday’s settings do you discover that all ten contain today’s version.</p><p>Nothing crashed. Every launch faithfully made a backup. That repetition pushed the useful old version out of the retention window.</p><p><strong>A full backup list does not necessarily contain a useful history.</strong> We tested the original code from an open-source project, asking whether the content from before a change survived.</p><h2 id="why-this-small-change-caught-our-attention" tabindex="-1">Why this small change caught our attention <a class="header-anchor" href="#why-this-small-change-caught-our-attention" aria-label="Permalink to &quot;Why this small change caught our attention&quot;">​</a></h2><p>The source is <a href="https://github.com/yzhao062/anywhere-agents/commit/ce6457a830dead5e05c3a17f685f7ff32575ce20" target="_blank" rel="noreferrer">commit ce6457a in anywhere-agents</a>, by Yue Zhao, or yzhao062 on GitHub. The project helps AI coding tools share settings. One Python program merges shared configuration into a local file.</p><p>The upstream investigation found that repeatedly merging unchanged settings created identical backups and displaced useful older contents.</p><p>This matters to us because automated tools often synchronize on every launch. If each synchronization consumes a backup slot, opening more terminals can shorten recoverable history without changing a single setting.</p><p>The patch compares the proposed output with the existing bytes while holding the original file lock. Identical output means no write and no new backup.</p><h2 id="change-once-then-repeat" tabindex="-1">Change once, then repeat <a class="header-anchor" href="#change-once-then-repeat" aria-label="Permalink to &quot;Change once, then repeat&quot;">​</a></h2><p>In a temporary directory, we started with old settings, merged a new value, then performed 27 identical merges. Both versions ran their original file operations and locking code.</p><table tabindex="0"><thead><tr><th>Observation</th><th>Before the patch</th><th>After the patch</th></tr></thead><tbody><tr><td>Retained backups</td><td>10</td><td>1</td></tr><tr><td>Content from before the change survives</td><td>No</td><td>Yes</td></tr><tr><td>Backups identical to the current file</td><td>10</td><td>0</td></tr><tr><td>Identical merges change the target modification time</td><td>Yes</td><td>No</td></tr></tbody></table><p>The first merge really did save the old settings in both versions. Before the patch, later merges kept saving the new settings again until the first backup fell outside the ten-file window.</p><p>After the patch, unchanged merges stopped consuming that window. Fewer backup files preserved more useful history.</p><p><img src="'+h+'" alt="Repeated copies versus recoverable history"></p><p><em>Figure 1. One real change followed by 27 identical merges. Source: author illustration from our local original-code experiment. Each block is a retained backup, not an upstream consumer.</em></p><p>We also ran eight concurrent processes after the initial change. The old version retained nine backups; the patched version retained only the original old content. That supports the lock-protected check under these conditions, not a claim about every filesystem failure.</p><h2 id="what-does-unchanged-mean" tabindex="-1">What does “unchanged” mean? <a class="header-anchor" href="#what-does-unchanged-mean" aria-label="Permalink to &quot;What does “unchanged” mean?&quot;">​</a></h2><p>Next, we deliberately reformatted the target before each merge. Keys and values stayed the same; whitespace changed.</p><p>After 12 such rewrites, both versions retained ten backups and had evicted the original old settings. This does not contradict the patch: different formatting means different bytes. The implementation skips byte-identical writes; it does not promise ten semantically distinct revisions.</p><p>This was a constructed counterexample, not a reported production incident. It exposes a useful design question: should history preserve every write, or every meaningful change?</p><p>Ignoring formatting is not automatically the right answer. Comments, ordering and presentation can themselves be worth restoring. A comparison that is too coarse can discard changes that matter.</p><h2 id="try-recovering-not-just-counting" tabindex="-1">Try recovering, not just counting <a class="header-anchor" href="#try-recovering-not-just-counting" aria-label="Permalink to &quot;Try recovering, not just counting&quot;">​</a></h2><p>A practical check is small: change a harmless setting, restart or synchronize repeatedly, then look for the pre-change version. The target is specific: can you recover what existed before that change?</p><p>If you have found plenty of backups but not the version you needed, record when the setting changed and how often the tool restarted or synchronized afterward. That helps locate when repeated copies displaced useful history.</p><p>For developers, the formatting counterexample suggests another experiment: let two tools alternate writes to the same configuration, then compare retention by write count, distinct content and elapsed time. Each policy may lose something different. Formatting or comments can themselves be worth restoring, so deduplication should not be assumed to be the answer.</p><p>The tested improvement is clear: unchanged bytes no longer create backups, preserving the original revision in that scenario. It leaves one larger question: <strong>does a backup system promise the last few saves, or the changes a person needs to return to?</strong></p><details><summary>Versions, scope and reproduction</summary><p>The upstream investigation reported 27 consumers and 198 byte-identical backups. Those are <strong>upstream observations, not the scale of our experiment</strong>.</p><p>We ran the complete original Python merge module through its main entry point, using real Windows temporary files and its original locks. Six scenarios ran against both versions, producing 12 observations: identical merges, deliberate formatting rewrites, another real change, first installation, empty-merge refusal, and eight concurrent identical merges.</p><p>Base: <code>91c64c153f2034bf4aa88121cbe546cbf6a22aeb</code>. Patched revision: <code>ce6457a830dead5e05c3a17f685f7ff32575ce20</code>. Except for first installation, scenarios begin with an initial merge. The 27 repeats are not 27 real consumers. We used synthetic settings and did not test power loss or disk corruption.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-17-control-intent" target="_blank" rel="noreferrer">Results and reproduction scripts</a>. This experiment does not establish the same problem in CodeFlowMu.</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',29))])}const w=r(l,[["render",d]]);export{b as __pageData,w as default};
